SELECT state,count(*) n,sum(closing_value) total,count(*) FILTER(WHERE closing_value<=0) nonpositive,count(*) FILTER(WHERE closing_value IS NULL) missing_value,count(*) FILTER(WHERE closing_value>2000000) above_cap,count(*) FILTER(WHERE authority_entity_id IS NULL) missing_authority,count(*) FILTER(WHERE supplier_entity_id IS NULL) missing_supplier,count(*) FILTER(WHERE cpv_code IS NULL) missing_cpv,count(*) FILTER(WHERE finalization_date IS NULL) missing_finalization,count(*) FILTER(WHERE finalization_date<publication_date) negative_duration,count(*) FILTER(WHERE finalization_date>'2026-10-03'::date+interval '1 day') future_date,min(finalization_date) earliest,max(finalization_date) latest FROM core.direct_acquisitions GROUP BY state ORDER BY n DESC
